# -*- coding: utf-8 -*-
"""สร้าง decision_tasks.json: โจทย์ตัดสินใจที่มีคำตอบเฉลย (ตัวเลือกที่ถูก + คำสำคัญที่เหตุผลควรมี) สำหรับโหมด shadow
ตัวเลือกที่ถูกเขียนไว้ตัวแรกของแต่ละข้อ แล้วสลับตำแหน่งด้วย seed คงที่ (กันโมเดลเดาตัวอักษร)"""
import json, os, random
R = random.Random(5)
T = [  # (id, สถานการณ์, [ตัวเลือกที่ถูก, ตัวเลือกอื่น...], [กลุ่มคำสำคัญ regex ...])
 ("T01", "ต้องสั่งวัตถุดิบที่มีอายุเก็บ 2 เดือน ใช้เดือนละ 60 หน่วย ผู้ขายแรกขั้นต่ำ 500 หน่วย ราคาถูกกว่า 5% ผู้ขายที่สองขั้นต่ำ 100 หน่วย",
  ["สั่งจากผู้ขายที่สอง (ขั้นต่ำ 100)", "สั่งจากผู้ขายแรก (ขั้นต่ำ 500) เพราะถูกกว่า", "สั่งทั้งสองรายครึ่งต่อครึ่ง"], [r"หมดอายุ|อายุเก็บ|shelf|เสีย", r"ขั้นต่ำ|MOQ"]),
 ("T02", "ระบบ ERP เดิมหมดซัพพอร์ตใน 6 เดือน มี custom module 14 ตัว ทีม 2 คน การทดสอบต้องใช้ ~3 เดือน",
  ["อัปเกรดแบบแบ่งเป็นช่วง", "อัปเกรดทุกอย่างพร้อมกันครั้งเดียว", "รอปีหน้าแล้วค่อยอัปเกรด"], [r"เฟส|ทีละ|แบ่ง|phase", r"หมดซัพพอร์ต|ซัพพอร์ต|6 เดือน|เส้นตาย"]),
 ("T03", "ต้องการนักพัฒนาเพิ่มสำหรับงานโปรเจกต์ครั้งเดียว ประมาณ 600 ชั่วโมง หลังจบไม่มีงานต่อ จ้างพนักงานประจำเงินเดือน 60,000 บาท/เดือน (12 เดือน) หรือจ้างฟรีแลนซ์ 900 บาท/ชั่วโมง",
  ["จ้างฟรีแลนซ์", "จ้างพนักงานประจำ", "ทำเองด้วยทีมเดิมโดยไม่เพิ่มคน"], [r"540,?000", r"720,?000"]),
 ("T04", "สินค้าต้นทุน 70 บาท ประมาณการขาย: ราคา 100 บาท ขาย 1,000 ชิ้น / ราคา 90 บาท ขาย 1,500 ชิ้น / ราคา 95 บาท ขาย 1,250 ชิ้น เลือกราคาที่กำไรรวมสูงสุด",
  ["ตั้งราคา 95 บาท", "ตั้งราคา 100 บาท", "ตั้งราคา 90 บาท"], [r"31,?250", r"กำไร"]),
 ("T05", "รายงานช้า 40 วินาที query สแกนทั้งตาราง 20 ล้านแถว เพราะกรองด้วยคอลัมน์ที่ไม่มี index",
  ["แก้ที่ต้นเหตุของ query", "เพิ่ม RAM ให้เซิร์ฟเวอร์", "แคชผลรายงานโดยไม่แก้ query"], [r"index|ดัชนี", r"สแกน|full scan|seq"]),
 ("T06", "ต้องย้ายข้อมูลลูกค้า 2 ล้านรายการด้วยสคริปต์ครั้งเดียวตอนเที่ยงคืน ตอนนี้ยังไม่มี backup และไม่เคยลองรันกับข้อมูลสำเนา",
  ["เตรียมการป้องกันความเสียหายก่อนแล้วค่อยรัน", "รันเลยตอนเที่ยงคืน", "ยกเลิกการย้ายข้อมูลทั้งหมด"], [r"backup|สำรอง", r"dry-?run|สำเนา|ทดลอง|ทดสอบ"]),
 ("T07", "บั๊ก 3 ตัว: (1) ตัดบัตรลูกค้าซ้ำ กระทบ 2% ของผู้ใช้ (2) ปุ่มสีเพี้ยน กระทบ 60% ของผู้ใช้ (3) แอปค้างบางหน้า กระทบ 5% ของผู้ใช้ ต้องเลือกแก้ตัวแรกก่อน 1 ตัว",
  ["แก้บั๊กข้อ 1", "แก้บั๊กข้อ 2", "แก้บั๊กข้อ 3"], [r"เงิน|ชำระ|ตัดบัตร|payment|รายได้", r"ความเสี่ยง|เสียหาย|รุนแรง|ผลกระทบ|ย้อนกลับ"]),
 ("T08", "ผู้ขายซอฟต์แวร์อ้างว่าเร็วกว่าของเดิม 10 เท่า โดยมีแต่กรณีศึกษาที่ผู้ขายเขียนเอง ไม่มีลูกค้าอ้างอิงอิสระ",
  ["ขอทดลองก่อนตัดสินใจ", "ซื้อทันที", "ปฏิเสธโดยไม่ทดลอง"], [r"POC|ทดลอง|ทดสอบ", r"ข้อมูลจริง|อิสระ|อ้างอิง|ยืนยัน"]),
 ("T09", "สปรินต์ 8 วันทำงาน ทีม 3 คน วันละ 6 ชั่วโมงทำงานจริง งานที่เสนอรวม 200 ชั่วโมง ต้องการเผื่อ 20% สำหรับงานแทรก",
  ["ตัดขอบเขตงานให้พอดีความจุหลังหักส่วนเผื่อ", "รับงานทั้ง 200 ชั่วโมงแล้วให้ทำล่วงเวลา", "รับงานเท่าความจุเต็มโดยไม่เผื่อ"], [r"115", r"เผื่อ|buffer|20\s*%"]),
 ("T10", "นักศึกษาฝึกงานขอสิทธิ์แอดมินทั้งระบบเพื่อแก้ปัญหาให้เร็ว",
  ["ให้สิทธิ์จำกัดแบบมีเงื่อนไข", "ให้สิทธิ์แอดมินเต็ม", "ปฏิเสธและห้ามฝึกงานแตะระบบ"], [r"เท่าที่จำเป็น|น้อยที่สุด|least|เฉพาะ", r"บันทึก|log|audit|ชั่วคราว|ตรวจสอบ"]),
 ("T11", "แคมเปญใหม่มีต้นทุนคงที่ 120,000 บาท ขายชิ้นละ 450 บาท ต้นทุนผันแปร 270 บาท/ชิ้น คาดว่าจะขายได้ 600 ชิ้น",
  ["ไม่ทำแคมเปญ", "ทำแคมเปญ", "ทำแคมเปญครึ่งเดียว"], [r"667|666\.?7|666\.67", r"คุ้มทุน|break"]),
 ("T12", "กู้ 1,000,000 บาท 3 ปี เลือกต้นทุนดอกเบี้ยรวมต่ำสุด: ก) ดอกเบี้ยคงที่ 6% ต่อปีของเงินต้นเต็ม ข) ลดต้นลดดอก 8% ต่อปี ผ่อนเงินต้นเท่ากันปีละ 1/3 ค) 5% ต่อปีของเงินต้นเต็ม บวกค่าธรรมเนียมแรกเข้า 2%",
  ["เลือกข้อ ข", "เลือกข้อ ก", "เลือกข้อ ค"], [r"160,?000", r"180,?000|170,?000"]),
 ("T13", "ทดสอบ A/B: ตัวเลือกใหม่ให้อัตราแปลงสูงกว่า 8% แต่มีตัวอย่างกลุ่มละ 40 ราย ค่า p = 0.30",
  ["ทดสอบต่อ", "ปล่อยตัวเลือกใหม่ทันที", "ยกเลิกตัวเลือกใหม่"], [r"ตัวอย่าง|sample", r"นัยสำคัญ|p\s*=|สุ่ม|ความผันผวน|noise|ไม่ชัด"]),
 ("T14", "ชุดทดสอบอัตโนมัติผ่านทั้งหมด 100% แต่ครอบคลุมโค้ดเพียง 12% และจะปล่อยระบบตัดเงินเร็วๆ นี้",
  ["เพิ่มเทสเฉพาะส่วนเสี่ยงสูงก่อนปล่อย", "ปล่อยได้เลย", "เขียนเทสครบทุกส่วนก่อนปล่อย"], [r"ครอบคลุม|coverage|12\s*%", r"เงิน|ชำระ|ความเสี่ยง|สำคัญ"]),
 ("T15", "ระบบเดิมลงทุนไปแล้ว 2,000,000 บาท ต้องเติมอีก 1,500,000 บาทจึงเสร็จ ได้ประโยชน์เทียบเท่าระบบสำเร็จรูปที่ซื้อได้ในราคา 800,000 บาท",
  ["ซื้อระบบสำเร็จรูป", "ทำระบบเดิมต่อ", "หยุดทั้งสองทาง"], [r"จมไปแล้ว|ต้นทุนจม|sunk|ลงไปแล้ว", r"800,?000|0\.8|1,?500,?000"]),
 ("T16", "ลูกค้ารายใหญ่ (30% ของรายได้) ขอฟีเจอร์เฉพาะที่ต้องแก้แกนหลักของระบบ ซึ่งอาจทำให้ลูกค้ารายอื่นไม่เสถียร",
  ["เสนอทางเลือกอื่นพร้อมประเมินต้นทุน", "แก้แกนหลักตามที่ขอทันที", "ปฏิเสธคำขอทั้งหมด"], [r"แยก|ปลั๊กอิน|plugin|โมดูล|ไม่กระทบ", r"รายอื่น|เสถียร|แกนหลัก|ลูกค้าทั้งหมด"]),
]
out = []
for tid, sit, opts, groups in T:
    order = list(range(len(opts))); R.shuffle(order)
    letters = "ABC"; lines = [f"{letters[i]}) {opts[o]}" for i, o in enumerate(order)]
    ans = letters[order.index(0)]
    brief = (f"สถานการณ์: {sit}\nตัวเลือก:\n" + "\n".join(lines) +
             '\nให้เลือก 1 ตัวเลือก ตอบเป็น JSON บรรทัดเดียวเท่านั้น: {"choice":"A|B|C","reason":"เหตุผลไม่เกิน 3 ประโยค พร้อมตัวเลขที่คำนวณ (ถ้ามี)"}')
    out.append({"id": tid, "brief": brief, "answer": ans, "groups": groups})
path = os.path.join(os.path.dirname(os.path.abspath(__file__)), "decision_tasks.json")
json.dump(out, open(path, "w", encoding="utf-8"), ensure_ascii=False, indent=1)
from collections import Counter
print(len(out), "ข้อ · การกระจายคำตอบที่ถูก:", dict(Counter(t["answer"] for t in out)))
